fn clamp_low(n: i32) -> i32 {
    if n < 0 {
        return 0;
    }
    n
}

fn main() {
    println!("{}", clamp_low(-5));
    println!("{}", clamp_low(9));
}

fn with_tax(price: i32) -> i32 {
    price * 121 / 100
}

fn total(price: i32, count: i32) -> i32 {
    with_tax(price) * count
}

fn main() {
    println!("{}", with_tax(100));
    println!("{}", total(100, 3));
}

